import os
import random
import struct
from typing import List

# Data type: arbitrary binary data
# Goal: Produce seeded, interesting raw byte buffers suitable as:
#  - src for compression (various APIs)
#  - compressed input for decompression (may be arbitrary; safe APIs handle errors)
#  - dictionary buffers
# Constraints:
#  - Return bytes, length <= 4096
#  - Deterministic per seed but with diversity across seeds
# Strategy:
#  - Generate a variety of binary patterns: repetitive, incremental, ASCII text, UTF-8-like, high-entropy, structured headers,
#    and mixtures to exercise different LZ4 paths (matches, literals, small/large runs).
#  - Vary length across a wide range, biasing to small/medium sizes often used in stubs (<= ~2048) but sometimes larger up to 4096.
#  - Include optional dictionary-like prefix sections followed by payload to mimic realistic scenarios.

_ASCII_WORDS = (
    b"lorem ipsum dolor sit amet consectetur adipiscing elit ",
    b"the quick brown fox jumps over the lazy dog ",
    b"LZ4 fast compression test data ",
    b"0123456789abcdef ",
)


def _rnd(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _pattern_repeat(r: random.Random, length: int) -> bytes:
    # Choose a small motif size to create strong repetition
    motif_len = r.choice([1, 2, 3, 4, 5, 7, 8, 16, 32])
    motif = _rnd(r, motif_len)
    return (motif * (length // motif_len + 1))[:length]


def _pattern_incremental(length: int, start: int) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(length))


def _pattern_ascii(r: random.Random, length: int) -> bytes:
    buf = bytearray()
    while len(buf) < length:
        s = r.choice(_ASCII_WORDS)
        buf.extend(s)
        # Occasionally insert newline or punctuation
        if r.random() < 0.2:
            buf.append(r.choice([10, 13, 9, ord(','), ord('.'), ord('!'), ord('?')]))
    return bytes(buf[:length])


def _pattern_utf8ish(r: random.Random, length: int) -> bytes:
    # Build roughly valid UTF-8 sequences mixed with ASCII
    out = bytearray()
    while len(out) < length:
        p = r.random()
        if p < 0.6:
            out.append(r.randrange(0x20, 0x7F))
        elif p < 0.8:
            # 2-byte sequence
            cp = r.randrange(0x80, 0x7FF)
            out.extend(bytes([(0xC0 | (cp >> 6)), (0x80 | (cp & 0x3F))]))
        elif p < 0.95:
            # 3-byte
            cp = r.randrange(0x800, 0xFFFF)
            out.extend(bytes([
                0xE0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F),
            ]))
        else:
            # 4-byte
            cp = r.randrange(0x10000, 0x10FFFF)
            out.extend(bytes([
                0xF0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3F),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F),
            ]))
    return bytes(out[:length])


def _pattern_high_entropy(r: random.Random, length: int) -> bytes:
    # High-entropy payload that barely compresses
    return _rnd(r, length)


def _pattern_runs(r: random.Random, length: int) -> bytes:
    # Alternate long runs of a single byte with small random gaps
    out = bytearray()
    while len(out) < length:
        b = r.randrange(256)
        run = r.randrange(1, min(1024, length - len(out)) + 1)
        out.extend(bytes([b]) * run)
        if len(out) >= length:
            break
        gap = r.randrange(0, min(16, length - len(out)) + 1)
        out.extend(_rnd(r, gap))
    return bytes(out[:length])


def _mix_chunks(r: random.Random, length: int) -> bytes:
    # Build by concatenating varied chunk types
    patterns = [
        lambda n: _pattern_repeat(r, n),
        lambda n: _pattern_incremental(n, r.randrange(256)),
        lambda n: _pattern_ascii(r, n),
        lambda n: _pattern_utf8ish(r, n),
        lambda n: _pattern_high_entropy(r, n),
        lambda n: _pattern_runs(r, n),
    ]
    out = bytearray()
    while len(out) < length:
        remaining = length - len(out)
        chunk_len = r.randrange(1, min(512, remaining) + 1)
        pat = r.choice(patterns)
        out.extend(pat(chunk_len))
    return bytes(out)


def _maybe_add_dict_prefix(r: random.Random, payload: bytes) -> bytes:
    # Sometimes prefix the buffer with a plausible dictionary section (64KB max in LZ4 context).
    if r.random() < 0.5:
        dict_len = r.randrange(0, min(64 * 1024, 1024, 4096 - len(payload)) + 1)
        if dict_len > 0:
            # Dictionary itself uses repetitive/ASCII to make matches likely
            dict_pat = r.choice([
                lambda n: _pattern_repeat(r, n),
                lambda n: _pattern_ascii(r, n),
                lambda n: _pattern_incremental(n, r.randrange(256)),
            ])
            dict_bytes = dict_pat(dict_len)
            return dict_bytes + payload
    return payload


def _size_for_seed(r: random.Random) -> int:
    # Tri-modal size distribution: small (1..64), medium (65..2048), large (2049..4096)
    p = r.random()
    if p < 0.5:
        return r.randint(1, 64)
    elif p < 0.9:
        return r.randint(65, 2048)
    else:
        return r.randint(2049, 4096)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    total_len = _size_for_seed(r)

    # Choose a primary composition strategy
    choice = r.random()
    if choice < 0.15:
        data = _pattern_repeat(r, total_len)
    elif choice < 0.30:
        data = _pattern_incremental(total_len, r.randrange(256))
    elif choice < 0.45:
        data = _pattern_ascii(r, total_len)
    elif choice < 0.60:
        data = _pattern_utf8ish(r, total_len)
    elif choice < 0.75:
        data = _pattern_runs(r, total_len)
    elif choice < 0.90:
        data = _pattern_high_entropy(r, total_len)
    else:
        data = _mix_chunks(r, total_len)

    # Optionally add a small header-like prolog to introduce low-entropy then entropy shift
    if r.random() < 0.35 and len(data) + 8 <= 4096:
        header = bytearray()
        header.extend(b"LZ4F\x01")  # recognizable but not required
        header.extend(struct.pack("<H", r.randrange(0, 0xFFFF)))
        data = bytes(header) + data

    # Optionally prefix with a dictionary-like section (helps compress_continue and usingDict scenarios)
    data = _maybe_add_dict_prefix(r, data)

    # Ensure final size limit
    if len(data) > 4096:
        data = data[:4096]

    return data
